// @FIGURE_CODE_BEGIN
// ELEMENT SPEC (one line per element type)
// circle, ordinary        -> CircleGeometry(0.45,48)            #000000
// circle, group median    -> CircleGeometry(0.45) #FFFFFF + RingGeometry(0.36,0.45) #000000
// straight arrow          -> ribbon BufferGeometry (w 0.085) + flat triangle head (0.45 long, 0.34 wide) #000000
