  const rows = (c === 5) ? [1, 2, 3] : [0, 1, 2, 3, 4];
  const groupSize = rows.length;
  for (const r of rows) {
    const X = COLX[c], Y = ROWY[r];
    let chain;
    if (r === 2) chain = (c === 2) ? 'both' : (c > 2 ? 'g' : 'l');
    else if (r > 2) chain = (c >= 2) ? 'g' : null;
    else chain = (c <= 2) ? 'l' : null;

    if (r === 2) {
      // black version (phase 0 only)
      const bm = new THREE.MeshBasicMaterial({ color: BLACK, side: THREE.DoubleSide });
      const bmesh = new THREE.Mesh(new THREE.CircleGeometry(R, 48), bm);
      bmesh.position.set(X, Y, 0.02);
      addEl(bmesh, [bm], { show: () => phase === 0, chain, color: BLACK, order: 2 });
      // white disk + black ring (phase >= 1)
      const fm = new THREE.MeshBasicMaterial({ color: WHITE, side: THREE.DoubleSide });
      const fmesh = new THREE.Mesh(new THREE.CircleGeometry(R, 48), fm);
      fmesh.position.set(X, Y, 0.02);
      addEl(fmesh, [fm], { show: () => phase >= 1, chain, color: WHITE, accentable: false, order: 2 });
      const rm = new THREE.MeshBasicMaterial({ color: BLACK, side: THREE.DoubleSide });
      const rmesh = new THREE.Mesh(new THREE.RingGeometry(R - 0.09, R, 48), rm);
      rmesh.position.set(X, Y, 0.03);
      addEl(rmesh, [rm], { show: () => phase >= 1, chain, color: BLACK, order: 2 });
    } else {
      const m = new THREE.MeshBasicMaterial({ color: BLACK, side: THREE.DoubleSide });
      const mesh = new THREE.Mesh(new THREE.CircleGeometry(R, 48), m);
      mesh.position.set(X, Y, 0.02);
      addEl(mesh, [m], { show: always, chain, color: BLACK, order: 2 });
    }

    // invisible hover/click disc
    const hm = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0, depthTest: false, depthWrite: false });
    const hd = new THREE.Mesh(new THREE.CircleGeometry(0.62, 24), hm);
    hd.position.set(X, Y, 0.06);
    hd.renderOrder = 3;
    scene.add(hd);
    hitDiscs.push(hd);

    const isX = (c === 2 && r === 2);
    let tip, body;
    if (isX) {
      tip = 'x — the median of the medians';
      body = 'x is the median of the six group medians. Three medians (including x) are ≥ x and three are ≤ x. Each of those medians drags its two larger (or two smaller) group-mates along, so at least about 3n/10 elements are forced to each side of x. Click x to light up the certifying chains.';
    } else if (r === 2) {
      tip = `Median of group ${c + 1}` + (c > 2 ? ' — known ≥ x' : ' — known ≤ x');
      body = `This white disk is the median of column ${c + 1}: it is greater than 2 elements and less than 2 elements of its own group. The horizontal arrow on the median row compares it with x, so everything on its far side inherits an ordering with x through a two-step chain.`;
    } else {
      const rel = r > 2 ? 'greater than' : 'less than';
      tip = `Group ${c + 1}, element ${r + 1} of ${groupSize} — ${rel} its group median`;
      body = `Column ${c + 1} is sorted with the smallest element at the top. The vertical/curved arrows show this element is ${rel} its group's median. If that median is itself ordered with x, this element is ordered with x too — without ever being compared with x directly.`;
    }
    registerInteractive(hd, { title: isX ? 'x: median of medians' : (r === 2 ? 'Group median' : 'Group member'), tooltip: tip, body });
    if (isX) xHitDisc = hd;
  }
}

/* ── camera (after all geometry) ─────────────────────────────────────── */
setCameraView({ projection: 'orthographic', axisScreenAngles: null, rollDeg: 0, heightFraction: 0.72 });

/* ── label ───────────────────────────────────────────────────────────── */
const labelX = addLabel('<i>x</i>', new THREE.Vector3(-0.62, -0.82, 0.05), { fontSize: '26px' });
labelX.div.style.fontFamily = '"Times New Roman", Times, serif';
labelX.div.style.fontStyle = 'italic';
labelX.div.style.transition = 'opacity 0.25s ease';
labelX.div.style.opacity = '0';

/* ── state refresh ───────────────────────────────────────────────────── */
function refresh() {
  for (const e of reg) {
    const vis = e.show();
    let op = vis ? 1 : 0;
    let col = e.baseColor;
    if (highlight && vis) {
      const inChain = e.chain === 'both' || (e.chain && e.chain === side);
      if (inChain) { if (e.accentable) col = ACCENT; }
      else op = 0.22;
    }
    e.tgt = op;
    for (const m of e.mats) if (m.color) m.color.setHex(col);
  }
  labelX.div.style.opacity = phase >= 2 ? '1' : '0';
  labelX.div.style.color = (highlight ? '#d2402a' : '#111');

  document.querySelectorAll('.phaseBtn').forEach(b => {
    b.classList.toggle('active', Number(b.dataset.p) === phase);
  });
  document.querySelectorAll('.sideBtn').forEach(b => {
    b.classList.toggle('active', b.dataset.s === side);
  });
  const cb = document.getElementById('btnChains');
  if (cb) cb.classList.toggle('active', highlight);
}

/* ── opacity tween loop ──────────────────────────────────────────────── */
let _lastT = performance.now();
function tweenLoop() {
  requestAnimationFrame(tweenLoop);
  const now = performance.now();
  const dt = Math.min(0.06, (now - _lastT) / 1000);
  _lastT = now;
  const k = 1 - Math.exp(-dt / 0.09);
  for (const e of reg) {
    if (e.cur !== e.tgt) {
      e.cur += (e.tgt - e.cur) * k;
      if (Math.abs(e.tgt - e.cur) < 0.003) e.cur = e.tgt;
      for (const m of e.mats) m.opacity = e.cur;
    }
    e.obj.visible = e.cur > 0.004;
  }
}
tweenLoop();

/* ── controls ────────────────────────────────────────────────────────── */
function setPhase(p) { phase = Math.max(0, Math.min(3, p)); refresh(); }
function setSide(s) { side = s; refresh(); }
function setHighlight(h) { highlight = h; refresh(); }

document.querySelectorAll('.phaseBtn').forEach(b => {
  b.addEventListener('click', () => setPhase(Number(b.dataset.p)));
});
document.querySelectorAll('.sideBtn').forEach(b => {
  b.addEventListener('click', () => setSide(b.dataset.s));
});
document.getElementById('btnChains').addEventListener('click', () => setHighlight(!highlight));

// click x in the figure to toggle the chains; click empty space to clear
const _ray = new THREE.Raycaster();
const _pt = new THREE.Vector2();
renderer.domElement.addEventListener('click', (ev) => {
  const rect = renderer.domElement.getBoundingClientRect();
  _pt.x = ((ev.clientX - rect.left) / rect.width) * 2 - 1;
  _pt.y = -((ev.clientY - rect.top) / rect.height) * 2 + 1;
  _ray.setFromCamera(_pt, camera);
  const hit = xHitDisc ? _ray.intersectObject(xHitDisc, false) : [];
  if (hit.length) setHighlight(!highlight);
  else if (highlight) setHighlight(false);
});

/* ── guided demo ─────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: '1 · Groups of five',
    text: 'The n elements are laid out as columns of 5; within each column the arrows run from larger elements up to smaller ones, so each group is already sorted — smallest at the top, largest at the bottom. The rightmost column is a leftover partial group.',
    state: { phase: 0 }
  },
  {
    title: '2 · Mark the group medians',
    text: "The middle circle of each group turns white: that group's median, known to be greater than two and less than two elements of its own column.",
    state: { phase: 1 }
  },
  {
    title: '3 · Choose x, the median of medians',
    text: 'Horizontal arrows along the row of white disks order the medians themselves. x is their median, so three of the six medians (x included) are at least x and three are at most x.',
    state: { phase: 2 }
  },
  {
    title: '4 · Count what must be greater',
    text: 'Each median greater than x drags its two larger group-mates with it. The shaded stepped block collects every element the arrow chains force above x — at least about 3n/10 of the input — so the partition can never be badly lopsided.',
    state: { phase: 3, side: 'g' }
  },
  {
    title: '5 · The mirror-image half',
    text: 'Flipping the shading to the other side shows the symmetric block of elements forced below x, giving the matching 3n/10 bound and hence the linear-time recurrence.',
    state: { phase: 3, side: 'l' }
  }
];
let stepIdx = 0;
function goToStep(i) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, i));
  const s = STEPS[stepIdx];
  if (s.state.phase !== undefined) phase = s.state.phase;
  if (s.state.side !== undefined) side = s.state.side;
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepText').textContent = s.text;
  document.getElementById('btnPrev').disabled = (stepIdx === 0);
  document.getElementById('btnNext').disabled = (stepIdx === STEPS.length - 1);
  refresh();
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));

goToStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

